# Next.js 15 to 16: Complete Migration Guide

## Version Requirements
- **Node.js**: 20.9+ (18.x no longer supported)
- **TypeScript**: 5.1+
- **Browsers**: Chrome 111+, Edge 111+, Firefox 111+, Safari 16.4+

## Breaking Changes & Removals

### 1. **AMP Support - REMOVED**
```ts
// ❌ Remove all AMP references
export const config = { amp: true }  // DELETE
useAmp()  // DELETE
```

### 2. **`middleware.ts` → `proxy.ts`**
```ts
// middleware.ts (DEPRECATED)
export function middleware(request: NextRequest) {
  return NextResponse.redirect(new URL('/home', request.url));
}

// ✅ New: proxy.ts
export default function proxy(request: NextRequest) {
  return NextResponse.redirect(new URL('/home', request.url));
}
```

### 3. **`next lint` Command - REMOVED**
```bash
# ❌ This no longer works
next lint

# ✅ Use directly with ESLint or Biome
npx eslint .
# Or run the migration
npx @next/codemod@canary next-lint-to-eslint-cli .
```

### 4. **Config Options - REMOVED**
```ts
// ❌ All removed from next.config.js
devIndicators: {
  appIsrStatus: true,
  buildActivity: true,
  buildActivityPosition: 'bottom-right'
}
serverRuntimeConfig: {}
publicRuntimeConfig: {}

// ✅ Use environment variables instead
// .env
API_SECRET=secret
NEXT_PUBLIC_API_URL=url
```

### 5. **Experimental Flags - REMOVED/RENAMED**
```ts
// ❌ Old experimental flags
experimental: {
  turbopack: true,      // Move to top-level
  dynamicIO: true,      // Renamed to cacheComponents
  ppr: true,           // Removed - use cacheComponents
}

// ✅ New structure
const nextConfig = {
  turbopack: true,  // Now top-level
  cacheComponents: true,  // Replaces dynamicIO and ppr
};
```

### 6. **Async `params` & `searchParams` - REQUIRED**
```ts
// ❌ Old sync access (no longer works)
export default function Page({ params, searchParams }) {
  const id = params.id;
  const query = searchParams.q;
}

// ✅ Must use async
export default async function Page({ params, searchParams }) {
  const { id } = await params;
  const { q } = await searchParams;
}
```

### 7. **Async Functions - `cookies()`, `headers()`, `draftMode()`**
```ts
// ❌ Old sync access (no longer works)
import { cookies, headers } from 'next/headers';

export default function Page() {
  const cookieStore = cookies();
  const headersList = headers();
}

// ✅ Must use async
import { cookies, headers } from 'next/headers';

export default async function Page() {
  const cookieStore = await cookies();
  const headersList = await headers();
}
```

### 8. **Metadata Image Route `params` - NOW ASYNC**
```ts
// ❌ Old sync params
export async function generateImageMetadata({ params }) {
  const id = params.id;  // String
}

// ✅ Now async
export async function generateImageMetadata({ params }) {
  const id = await params.id;  // Promise<string>
}
```

### 9. **`next/image` Local Query Strings**
```ts
// ❌ This now requires configuration
<Image src="/images/photo.png?v=1" alt="Photo" />

// ✅ Add images.localPatterns config
const nextConfig = {
  images: {
    localPatterns: [
      {
        pathname: '/images/.*',
        search: '',  // Allow all query strings
      },
    ],
  },
};
```

### 10. **Parallel Routes `default.js` - NOW REQUIRED**
```ts
// ❌ Old behavior - optional default.js
app/
  @modal/page.js

// ✅ All parallel route slots now require explicit default.js
app/
  @modal/
    default.js  // REQUIRED - must export null or notFound()
    page.js

// default.js should contain:
export default function Default() {
  return null;  // or notFound()
}
```

### 11. **`unstable_rootParams()` - REMOVED**
```ts
// ❌ Removed
export async function unstable_rootParams() {}

// ✅ Alternative API coming in next minor version
```

## Default Behavior Changes

### 12. **Turbopack is Now Default**
```bash
# Turbopack is automatic - no config needed
next dev
next build

# ✅ To use webpack explicitly
next dev --webpack
next build --webpack
```

### 13. **Image Configuration Defaults Changed**
```ts
const nextConfig = {
  images: {
    // minimumCacheTTL: 60,  → now 14400 (4 hours)
    // imageSizes: [16, 32, 48, 64, 96, 128, 256, 384]  → 16 removed
    // qualities: [1..100]  → now [75]
    dangerouslyAllowLocalIP: false,  // New security default (was unset)
    maximumRedirects: 3,  // Was unlimited
  },
};
```

### 14. **ESLint Config Format**
```js
// ❌ Old legacy config (if you have one)
module.exports = {
  plugins: ['@next/next'],
  rules: {},
};

// ✅ Update to ESLint Flat Config format
import nextPlugin from '@next/eslint-plugin-next';

export default [
  {
    plugins: {
      '@next/next': nextPlugin,
    },
    rules: {
      '@next/next/rule-name': 'error',
    },
  },
];
```

### 15. **Scroll Behavior - Auto-smooth REMOVED**
```ts
// ❌ Automatic smooth scrolling removed
// To restore add to HTML:

<html data-scroll-behavior="smooth">
  {/* ... */}
</html>
```

## New Caching APIs

### 16. **`revalidateTag()` - Now Requires `cacheLife` Profile**
```ts
// ❌ Old single argument (deprecated)
revalidateTag('blog-posts');

// ✅ New: requires cacheLife profile
import { revalidateTag } from 'next/cache';

// Built-in profiles
revalidateTag('blog-posts', 'max');      // Long-lived with SWR
revalidateTag('news-feed', 'hours');     // 1 hour
revalidateTag('analytics', 'days');      // 1 day

// Custom inline
revalidateTag('products', { expire: 3600 });  // 1 hour

// In next.config.ts for reusable profiles:
const nextConfig = {
  cacheLife: {
    news: 60 * 60,        // 1 hour
    premium: 60 * 60 * 24, // 1 day
  },
};
```

### 17. **`updateTag()` - New Server Action API**
```ts
'use server';

import { updateTag } from 'next/cache';

export async function updateUserProfile(userId: string, profile: Profile) {
  await db.users.update(userId, profile);

  // Immediately refresh - read-your-writes semantics
  updateTag(`user-${userId}`);
}
```

### 18. **`refresh()` - New Server Action API**
```ts
'use server';

import { refresh } from 'next/cache';

export async function markNotificationAsRead(notificationId: string) {
  await db.notifications.markAsRead(notificationId);

  // Refresh uncached data only (notification count in header)
  refresh();
}
```

## New Features (Opt-In)

### 19. **Cache Components - Enable in Config**
```ts
// next.config.ts
const nextConfig = {
  cacheComponents: true,
};

export default nextConfig;

// Usage in components
'use cache';  // New directive

export default function Component() {
  // This component is now cached
}
```

### 20. **React Compiler - Stable (Optional)**
```ts
// next.config.ts
const nextConfig = {
  reactCompiler: true,  // Moved from experimental
};

export default nextConfig;

// Install latest
npm install babel-plugin-react-compiler@latest
```

## Migration Checklist

- [ ] Update Node.js to 20.9+
- [ ] Update TypeScript to 5.1+
- [ ] Run `npx @next/codemod@canary upgrade latest`
- [ ] Remove all AMP code
- [ ] Rename `middleware.ts` → `proxy.ts`
- [ ] Convert `params` and `searchParams` to async
- [ ] Convert `cookies()`, `headers()`, `draftMode()` to async
- [ ] Update `revalidateTag()` calls with `cacheLife` profile
- [ ] Add `default.js` to all parallel routes
- [ ] Update ESLint config to Flat Config format
- [ ] Remove `devIndicators`, `serverRuntimeConfig`, `publicRuntimeConfig`
- [ ] Move `experimental.turbopack` to top-level `turbopack`
- [ ] Test image optimization with new defaults
- [ ] Review and remove other deprecated configs
- [ ] Test with `next dev` and `next build`

